/* The sector packs (general EPC, manufacturing) name some agents of their own.
   They get a deterministic avatar from the same five glyphs and gradient pairs,
   so every pack looks like one set rather than a gap where the art is missing. */
const AGAV_GLYPH = [
  '<path d="M24 9a15 15 0 1 1-10.6 25.6" fill="none" stroke="#fff" stroke-width="3.4" stroke-linecap="round" opacity=".55"></path><circle cx="24" cy="24" r="5.5" fill="#fff" opacity=".95"></circle>',
  '<g fill="none" stroke="#fff" stroke-width="3.4" stroke-linecap="round" stroke-linejoin="round"><path d="M16 15l8 9-8 9" opacity=".45"></path><path d="M27 15l8 9-8 9" opacity=".95"></path></g>',
  '<g fill="none" stroke="#fff" stroke-width="3.2" stroke-linecap="round"><path d="M10 19c3.5-4 6.5-4 10 0s6.5 4 10 0" opacity=".45"></path><path d="M10 26c3.5-4 6.5-4 10 0s6.5 4 10 0" opacity=".72"></path><path d="M10 33c3.5-4 6.5-4 10 0s6.5 4 10 0" opacity=".95"></path></g>',
  '<circle cx="17" cy="17" r="3.4" fill="#fff" opacity=".55"></circle><circle cx="31" cy="17" r="3.4" fill="#fff" opacity=".55"></circle><circle cx="17" cy="31" r="3.4" fill="#fff" opacity=".55"></circle><circle cx="31" cy="31" r="7" fill="#fff" opacity=".95"></circle>',
  '<g fill="#fff"><rect x="13" y="13" width="15" height="15" rx="4" opacity=".45"></rect><rect x="21" y="21" width="15" height="15" rx="4" opacity=".92"></rect></g>'
];
const AGAV_GRAD = [['orange-300', 'red-600'], ['brand-300', 'brand-600'], ['amber-300', 'amber-600'], ['red-300', 'red-600'], ['blue-300', 'blue-600'], ['blue-300', 'brand-700']];
function agentAv(n) {
  if (AGENT_AV[n]) return AGENT_AV[n];
  if (!n) return '';
  let h = 0; for (let i = 0; i < n.length; i++) h = (h * 31 + n.charCodeAt(i)) >>> 0;
  const gl = AGAV_GLYPH[h % AGAV_GLYPH.length], gr = AGAV_GRAD[(h >>> 3) % AGAV_GRAD.length];
  const id = 'avx' + h.toString(36);
  return `<svg class="agav" width="56" height="56" viewBox="0 0 48 48" role="img" aria-label="${n.replace(/[<>&"]/g, '')}">` +
    `<defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="var(--color-${gr[0]})"></stop><stop offset="1" stop-color="var(--color-${gr[1]})"></stop></linearGradient></defs>` +
    `<rect width="48" height="48" rx="24" fill="url(#${id})"></rect>${gl}</svg>`;
}
